import {ITEMS,migrate} from './model.mjs';
import {MATERIALS} from './resources.mjs';
import {MOVES} from './combat-moves.mjs';
import {moveCard} from './slot-pickers.mjs';
export const parisDay=(date=new Date())=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`};
export function shopCatalog(data){return [...data.items,...data.tms.map(i=>({...i,name:'CT · '+MOVES[i.move].name,desc:'Apprend '+MOVES[i.move].name+' à un Pokémon compatible.'})),...MATERIALS.map((i,n)=>({...i,key:'material-'+i.key,target:i.key,category:'material',image:'assets/materials/'+i.image,count:i.key==='heartScale'?3:1,price:[300,450,900,150,1000,1800][n]})),...ITEMS.map(i=>({...i,key:'held-'+i.key,target:i.key,category:'held',image:'assets/items/'+i.key+'.png',price:{common:250,rare:500,epic:950,legendary:1600}[i.rarity]}))]}
export function dailyOffers(catalog,day=parisDay()){const epoch=Math.floor(Date.parse(day+'T12:00:00Z')/86400000),take=(cat,n)=>{const pool=catalog.filter(i=>i.category===cat);return Array.from({length:Math.min(n,pool.length)},(_,k)=>pool[((epoch*n+k)%pool.length+pool.length)%pool.length])};return [...take('tm',4),...take('evolution',3),...take('material',2),...take('held',1)]}
export function buyOffer(state,catalog,day,key,now=new Date()){if(day!==parisDay(now))return {ok:false,reason:'Le stock a changé. Consulte les offres du jour.'};const item=dailyOffers(catalog,day).find(i=>i.key===key);if(!item)return{ok:false,reason:'Cette offre ne fait pas partie du stock du jour.'};state.shop||={purchases:{}};state.shop.purchases||={};const bought=state.shop.purchases[day]||[];if(bought.includes(key))return{ok:false,reason:'Tu as déjà acheté ce lot aujourd’hui.'};if(state.coins<item.price)return{ok:false,reason:'Pas assez de poussières d’étoiles.'};state.coins-=item.price;state.shop.purchases[day]=[...bought,key];if(item.category==='material')state.materials[item.target]=(state.materials[item.target]||0)+(item.count||1);else if(item.category==='held')state.inventory.push({uid:globalThis.crypto.randomUUID(),key:item.target});else{state.bag||={};state.bag[key]=(state.bag[key]||0)+(item.count||1)}return{ok:true,item}}
export class DailyShop{
 constructor(g,data){this.g=g;this.catalog=shopCatalog(data);this.day=parisDay();setInterval(()=>{if(g.page==='shop'&&!g.mode&&this.day!==parisDay()){this.day=parisDay();g.render()}},15000)}
 render(){const g=this.g,day=this.day=parisDay(),bought=g.state.shop.purchases?.[day]||[];return g.heading('LE COMPTOIR DES DRESSEURS','Boutique quotidienne','CT, objets d’évolution et trésors pour tes compagnons.')+`<section class="shop-banner panel"><div><span class="eyebrow">NOUVEAU STOCK CHAQUE JOUR</span><h2>De quoi préparer la prochaine aventure.</h2><p>Renouvellement à minuit, heure de Paris. Chaque lot est achetable une fois par jour.</p></div><span class="shop-currency">✦ ${g.state.coins.toLocaleString('fr')}<small>Poussières d’étoiles</small></span></section><div class="shop-toolbar"><span>Stock du ${day.split('-').reverse().join('/')}</span><button data-act="route" data-page="inventory">Ouvrir mon sac →</button></div><div class="daily-shop">${dailyOffers(this.catalog,day).map(i=>`<article class="shop-card ${i.category}"><span class="eyebrow">${{tm:'CAPACITÉ',evolution:'ÉVOLUTION',material:'ENTRAÎNEMENT',held:'ÉQUIPEMENT'}[i.category]}</span><img src="${i.image}" alt=""><h3>${g.escape(i.name)}${i.count>1?' ×'+i.count:''}</h3><p>${g.escape(i.desc||'Permet une évolution compatible.')}</p>${i.move?moveCard(MOVES[i.move],true):''}<small>1 lot / jour · Dans le sac : ${this.count(i)}</small><button class="${bought.includes(i.key)?'':'primary'}" data-act="shop-buy" data-key="${i.key}" data-day="${day}" ${bought.includes(i.key)||g.state.coins<i.price?'disabled':''}>${bought.includes(i.key)?'✓ Acheté aujourd’hui':'✦ '+i.price.toLocaleString('fr')}</button></article>`).join('')}</div><p class="sheet-note">Les CT se consomment au premier apprentissage. Les capacités apprises restent disponibles. Les échanges évolutifs utilisent ici un Câble Liaison ; les conditions particulières sont indiquées dans la fiche du Pokémon.</p>`}
 count(i){const s=this.g.state;return i.category==='held'?s.inventory.filter(x=>x.key===i.target).length:i.category==='material'?s.materials[i.target]||0:s.bag[i.key]||0}
 async buy(d){if(this.buying)return;this.buying=true;const run=()=>{let raw;try{raw=JSON.parse(localStorage.getItem('tour-infernale-v1'))}catch{}const state=raw?migrate(raw):this.g.state,result=buyOffer(state,this.catalog,d.day,d.key);this.g.state=state;if(result.ok)this.g.save();this.g.render();this.g.toast(result.ok?result.item.name+' ajouté au sac.':result.reason)};try{if(navigator.locks)await navigator.locks.request('pokeworld-daily-shop',run);else run()}finally{this.buying=false}}
 bag(){const g=this.g,items=this.catalog.filter(i=>['tm','evolution'].includes(i.category)&&g.state.bag[i.key]>0);return `<section class="progression-bag"><div class="section-title"><h2>CT & objets d’évolution</h2><button data-act="route" data-page="shop">Boutique quotidienne →</button></div><div class="item-grid">${items.map(i=>`<article class="item-card"><img src="${i.image}" alt=""><h3>${g.escape(i.name)}</h3><b>×${g.state.bag[i.key]}</b><p>${g.escape(i.desc||'À utiliser sur une évolution compatible.')}</p><button data-act="shop-use" data-key="${i.key}">Choisir un Pokémon →</button></article>`).join('')||'<p class="muted">Pas encore de CT ou d’objet d’évolution. Découvre le stock du jour à la boutique.</p>'}</div></section>`}
 use(key){const g=this.g,item=this.catalog.find(i=>i.key===key);if(!item||!g.state.bag[key])return;const keys=g.state.roster.filter(k=>item.move?g.dex[parseInt(k)].tmMoves?.includes(item.move):(g.poke(k).evolutions||[]).some(e=>e.items?.includes(key)));g.openModal(`<span class="eyebrow">${g.escape(item.name)}</span><h2>Choisis un partenaire</h2><p>${keys.length} Pokémon compatible${keys.length>1?'s':''}. ${item.move?'Choisis ensuite un emplacement de capacité.':'Les conditions d’évolution restent nécessaires.'}</p><div class="mon-grid">${g.monCards(keys,'shop-target')}</div><button data-act="close-modal">Retour</button>`);g.pendingShopItem=key;g.modal.querySelectorAll('[data-act="shop-target"]').forEach(b=>{b.dataset.item=key});const canvases=[...g.modal.querySelectorAll('canvas')];import('./art.mjs').then(Art=>{const loop=t=>{if(!g.modal.open||!canvases[0]?.isConnected)return;for(const c of canvases){const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);Art.drawMon(x,c.dataset.mon,c.width/2,c.height/2,90,'Idle',0,t/1000)}requestAnimationFrame(loop)};requestAnimationFrame(loop)})}
 target(d){const g=this.g,item=this.catalog.find(i=>i.key===d.item);if(!item)return;g.lab.key=d.key;g.lab.tab=item.move?'moves':'level';g.lab.picker=null;g.lab.open(d.key);g.lab.tab=item.move?'moves':'level';g.lab.open(d.key);if(item.move)g.toast('Clique un emplacement, puis choisis '+MOVES[item.move].name+'.')}
}
